+  color: var(--color-text-muted);
+  margin-top: 0.5rem;
+  font-size: 1rem;
+}
+
+main {
+  max-width: 720px;
+  margin: 0 auto;
+}
+
+.faq-list {
+  display: flex;
+  flex-direction: column;
+  gap: 0.75rem;
+}
+
+.example {
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius);
+  overflow: hidden;
+  transition: border-color var(--transition);
+}
+
+.example:has(.disclosure-btn[aria-expanded="true"]) {
+  border-color: #3d444d;
+}
+
+.example:focus-within {
+  border-color: var(--color-border-focus);
+}
+
+.disclosure-btn {
+  all: unset;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  width: 100%;
+  padding: 1.1rem 1.25rem;
+  cursor: pointer;
+  font-size: 1rem;
+  font-weight: 600;
+  color: var(--color-text);
+  gap: 1rem;
+  background: transparent;
+  transition: background-color var(--transition), color var(--transition);
+}
+
+.disclosure-btn:hover {
+  background-color: var(--color-surface-hover);
+  color: var(--color-accent-hover);
+}
+
+.disclosure-btn:focus-visible {
+  outline: 2px solid var(--color-border-focus);
+  outline-offset: -2px;
+  border-radius: calc(var(--radius) - 1px);
+}
+
+.btn-question {
+  flex: 1;
+  text-align: left;
+}
+
+.btn-icon {
+  flex-shrink: 0;
+  width: 1.25rem;
+  height: 1.25rem;
+  color: var(--color-icon);
+  transition: transform var(--transition), color var(--transition);
+}
+
+.disclosure-btn[aria-expanded="true"] .btn-icon {
+  transform: rotate(180deg);
+  color: var(--color-accent);
+}
+
+.disclosure-btn[aria-expanded="true"] .btn-question {
+  color: var(--color-accent);
+}
+
+.details {
+  overflow: hidden;
+  max-height: 0;
+  transition: max-height 300ms cubic-bezier(0.4, 0, 0.2, 1);
+}
+
+.details[data-open="true"] {
+  max-height: 600px;
+}
+
+.details-inner {
+  padding: 0 1.25rem 1.25rem;
+  border-top: 1px solid var(--color-border);
+  padding-top: 1rem;
+  color: var(--color-text-muted);
+  font-size: 0.95rem;
+  line-height: 1.7;
+}
+
+.details-inner p + p {
+  margin-top: 0.75rem;
+}
+
+.details-inner ul {
+  padding-left: 1.25rem;
+  margin-top: 0.5rem;
+}
+
+.details-inner li {
+  margin-bottom: 0.35rem;
+}
+
+.details-inner strong {
+  color: var(--color-text);
+}
+
+@media (max-width: 480px) {
+  .disclosure-btn {
+    padding: 1rem;
+    font-size: 0.95rem;
+  }
+  .details-inner {
+    padding: 0.875rem 1rem 1rem;
+    font-size: 0.9rem;
+  }
+}
+
+@media (forced-colors: active) {
+  .disclosure-btn {
+    border: 1px solid ButtonBorder;
+    color: ButtonText;
+  }
+  .disclosure-btn:hover,
+  .disclosure-btn:focus-visible {
+    outline: 2px solid Highlight;
+  }
+  .btn-icon {
+    fill: currentColor;
+    stroke: currentColor;
+  }
+}
+
')
